"""Decode browser-generated bytes with protoc, not the browser's own decoder."""
import hashlib
import hmac
import json
import sys
from steadyview_pb2 import Request
v = json.load(open(sys.argv[1]))
key, nonce = bytes.fromhex(v['key']), bytes.fromhex(v['nonce'])
proof = Request.FromString(bytes.fromhex(v['proof']))
assert proof.request_id == 17 and proof.WhichOneof('command') == 'authenticate'
assert proof.authenticate.proof == hmac.digest(key, b'SV-AUTH-v1' + nonce, 'sha256')
outer = Request.FromString(bytes.fromhex(v['secure']))
assert outer.WhichOneof('command') == 'secure_command'
cmd = outer.secure_command
assert cmd.sequence == 1
assert cmd.mac == hmac.digest(key, b'SV-CMD-v1' + nonce + cmd.sequence.to_bytes(4, 'little') + cmd.payload, 'sha256')
inner = Request.FromString(cmd.payload)
assert inner.request_id == outer.request_id == 18 and inner.WhichOneof('command') == 'get_state'
assert key == hashlib.pbkdf2_hmac('sha256', 'мой тестовый пароль'.encode(), bytes([0x42])*16, 600000, 32)
print('Web/protoc wire interoperability: passed')
